import React, { useCallback, useEffect, useRef, useState } from "react";
import { useHistory } from "react-router-dom";
import lottie from "lottie-web";
import { AGENTS } from "./LilAgents";
import { DEFAULTS, createWalkStates, stepWalk } from "./agentWalkEngine";
import coolMan from "./Cool Man.json";
import femaleWalk from "./Female Character Walking.json";
import "./LilAgentsLottie.css";

// Lottie variant — real authored walk cycles rather than shapes assembled in
// code. The clips only animate the gait; position, turning, resting and
// spacing still come from the shared walk engine.
//
// lottie-web is driven directly instead of via lottie-react so the playhead
// can be scrubbed per frame without pushing React state.

const prefersReducedMotion = () =>
  typeof window !== "undefined" &&
  window.matchMedia &&
  window.matchMedia("(prefers-reduced-motion: reduce)").matches;

// Ground covered by one full loop of the clip. This is the knob that stops the
// feet sliding: the playhead is scrubbed from distance travelled, so if the
// character appears to over- or under-step, change this rather than the speed.
const LOOP_DISTANCE = 0.085; // track fractions per clip loop

// On-screen height of the figure itself, ignoring whatever empty padding the
// clip was exported with.
const CHAR_HEIGHT = 172;

// The two clips frame their characters completely differently inside the same
// 1080x1080 canvas, so instead of hard-coding a crop we scrub the loop, union
// the drawn bounds, and retarget the SVG viewBox onto that. Anchored to the
// bottom so the feet land on the tiles whatever the export looked like.
function fitToContent(anim, container) {
  const svg = container.querySelector("svg");
  if (!svg) return;

  // getBBox() on the root <g> reports the clip region for precomp-based clips
  // rather than the drawn content, so measure the union of every painted
  // element's screen rect instead and convert back into viewBox units. That is
  // transform-safe and works whatever the export's structure.
  const svgRect = svg.getBoundingClientRect();
  if (!svgRect.width || !svgRect.height) return;
  const vb = svg.viewBox.baseVal;
  const sx = vb.width / svgRect.width;
  const sy = vb.height / svgRect.height;

  let l = Infinity;
  let t = Infinity;
  let r = -Infinity;
  let b = -Infinity;
  const samples = 12;
  const lastFrame = Math.max(anim.totalFrames - 1, 1);
  const painted = "path,rect,circle,ellipse,polygon,polyline,image";

  for (let i = 0; i < samples; i++) {
    anim.goToAndStop((i / samples) * lastFrame, true);
    svg.querySelectorAll(painted).forEach((el) => {
      const er = el.getBoundingClientRect();
      if (!er.width || !er.height) return;
      l = Math.min(l, er.left);
      t = Math.min(t, er.top);
      r = Math.max(r, er.right);
      b = Math.max(b, er.bottom);
    });
  }
  if (!isFinite(l) || r <= l || b <= t) return;

  const x0 = vb.x + (l - svgRect.left) * sx;
  const y0 = vb.y + (t - svgRect.top) * sy;
  const w = (r - l) * sx;
  const h = (b - t) * sy;
  const pad = h * 0.02;

  svg.setAttribute(
    "viewBox",
    `${x0 - pad} ${y0 - pad} ${w + pad * 2} ${h + pad * 2}`
  );
  svg.setAttribute("preserveAspectRatio", "xMidYMax meet");

  container.style.height = `${CHAR_HEIGHT}px`;
  container.style.width = `${Math.round(CHAR_HEIGHT * (w / h))}px`;
  anim.goToAndStop(0, true);
}

// `faces` is the direction the artwork already points, so the flip can be
// corrected per clip: 1 = drawn walking right, -1 = drawn walking left,
// 0 = front-facing (a flip would be meaningless).
//
// Cool Man is a three-quarter view but a directional one — nose, mustache tip
// and shoe toes all point right — so he mirrors cleanly and must not be marked
// front-facing, or he strides backwards on every leftward walk. The female clip
// is a left-facing side view.
const CLIPS = [
  { data: coolMan, key: "man", faces: 1 },
  { data: femaleWalk, key: "female", faces: -1 },
];

const WALK_OPTS = {
  speed: 0.06,
  // Personal space during ordinary strolling. 0.09 let their silhouettes clip
  // through each other on a close pass (the fitted figures are ~0.105 of the
  // track wide); this clears them. Getting close is now the meetup's job, not
  // something a loose minimum has to leave room for.
  minSep: 0.115,
  walkSpan: [0.3, 0.62],
  // Barely-there rests: the clips are walk cycles with no idle pose, so any
  // long pause just leaves a frozen character standing there.
  pause: [0.6, 1.6],
};

// ---------------------------------------------------------------------------
// Conversations
// ---------------------------------------------------------------------------
// Every so often the two stop wandering, walk to a shared midpoint, turn to
// face each other and actually talk. Scripted exchanges rather than the two
// independent random one-liners the bubbles used to be — a reply only lands if
// it answers the line before it.
//
// Each entry is [speakerIndex, line]; 0 is Bolt (builds), 1 is Pixel
// (researches). Keep them employer-agnostic, like AGENTS.phrases.
const CHATS = [
  [
    [0, "shipped it 🚀"],
    [1, "…straight to prod?"],
    [0, "tests were green"],
    [1, "you wrote one test"],
    [0, "it was a great test"],
  ],
  [
    [1, "read 60 papers today"],
    [0, "I shipped 3 features"],
    [1, "do they all work?"],
    [0, "one of them, beautifully"],
  ],
  [
    [0, "the RAG brain is live"],
    [1, "I fed it my notes"],
    [0, "it answers in your voice now"],
    [1, "…mildly terrifying"],
  ],
  [
    [1, "found a cool paper 📄"],
    [0, "can we ship it?"],
    [1, "it's 40 pages of proofs"],
    [0, "so that's a yes"],
  ],
  [
    [0, "prod's been quiet all day"],
    [1, "don't say that out loud"],
    [0, "why would that mat—"],
    [1, "*pager buzzes*"],
  ],
  [
    [1, "6 agents, all talking"],
    [0, "to each other?"],
    [1, "mostly about you"],
    [0, "good things?"],
    [1, "…benchmarks"],
  ],
];

// Said by whichever one you did NOT open, a beat after the terminal appears.
// No pronouns — the pair is deliberately unnamed beyond Bolt and Pixel.
const PEEKS = [
  "👀 what's on that screen?",
  "showing off again…",
  "ask about the RAG brain",
  "that uptime number is optimistic",
  "psst — /myspace has all 9",
];

// Centre-to-centre spacing they settle at to talk. The fitted figures are
// ~99px on a 940px track (0.105), so this leaves a sliver of air between them:
// close enough to read as one pair, never overlapping.
const MEET_GAP = 0.135;
// Seconds of ordinary strolling between conversations.
const MEET_EVERY = [20, 36];
// How far a speech bubble slides away from the partner, so two bubbles in a
// back-and-forth never sit on top of each other.
const BUBBLE_SHIFT = 46;

const lineSeconds = (text) => Math.min(2.8, 1.25 + text.length * 0.05);

// Walk one agent to a spot. Writes the same fields planWalk() does, so stepWalk
// carries it out as an ordinary walk — easing, gait and the distance-driven
// clip scrub all keep working.
function sendTo(self, to, now, opts) {
  // Already standing where it was headed — don't shuffle on the spot
  if (Math.abs(to - self.pos) < 0.015) {
    self.walking = false;
    return;
  }
  self.from = self.pos;
  self.to = to;
  self.dir = to > self.pos ? 1 : -1;
  self.facing = self.dir;
  self.duration = Math.max(0.8, Math.abs(to - self.pos) / opts.speed);
  self.startedAt = now;
  self.walking = true;
  self.travelled = 0;
}

// Send the pair to a shared midpoint, MEET_GAP apart. Both are planned in one
// go and the midpoint is pulled inside the track first: clamping the two
// targets independently would, for a meeting that lands near an edge, shorten
// one side only and squeeze the pair into an overlap.
function planMeetup(pair, now, opts) {
  const [lo, hi] = opts.bounds || DEFAULTS.bounds;
  const half = MEET_GAP / 2;
  const [a, b] = pair;
  const mid = Math.min(Math.max((a.pos + b.pos) / 2, lo + half), hi - half);
  const aIsLeft = a.pos <= b.pos;
  sendTo(a, mid + (aIsLeft ? -half : half), now, opts);
  sendTo(b, mid + (aIsLeft ? half : -half), now, opts);
}

function LilAgentsLottie() {
  const perchRef = useRef(null);
  const hostRefs = useRef([]); // wrapper divs, positioned by the engine
  const mountRefs = useRef([]); // lottie containers
  const animsRef = useRef([]);
  const [openId, setOpenId] = useState(null);
  // { i, text, chat } — one bubble at a time, so a conversation reads as a
  // single thread of speech handing back and forth rather than two monologues.
  const [speech, setSpeech] = useState(null);
  const [chatting, setChatting] = useState(false);
  const frozen = prefersReducedMotion();
  const history = useHistory();

  const statesRef = useRef(createWalkStates(AGENTS.length, WALK_OPTS));
  const states = statesRef.current;

  const openIdRef = useRef(null);
  useEffect(() => {
    openIdRef.current = openId;
  }, [openId]);

  // Every line issued takes a token; only the timeout belonging to the newest
  // one may clear the bubble. Without that, a solo one-liner scheduled three
  // seconds ago blanks the conversation line that replaced it.
  const speechTok = useRef(0);
  const showSpeech = useCallback((i, text, chat, hideMs) => {
    const tok = (speechTok.current += 1);
    setSpeech({ i, text, chat });
    if (hideMs) {
      window.setTimeout(() => {
        if (speechTok.current === tok) setSpeech(null);
      }, hideMs);
    }
  }, []);
  const clearSpeech = useCallback(() => {
    speechTok.current += 1;
    setSpeech(null);
  }, []);

  // phase: idle → approach (walking to meet) → talk → idle
  const chatRef = useRef({
    phase: "idle",
    script: null,
    scriptIdx: 0,
    line: -1,
    lineUntil: 0,
    approachUntil: 0,
    nextMeetAt: 10,
  });

  // Load the clips once, autoplay off — the frame is set by hand each tick
  useEffect(() => {
    const anims = mountRefs.current.map((container, i) => {
      if (!container) return null;
      return lottie.loadAnimation({
        container,
        renderer: "svg",
        loop: true,
        autoplay: false,
        animationData: CLIPS[i % CLIPS.length].data,
        rendererSettings: { preserveAspectRatio: "xMidYMid meet" },
      });
    });
    animsRef.current = anims;
    anims.forEach((a, i) => {
      if (!a) return;
      const fit = () => fitToContent(a, mountRefs.current[i]);
      if (a.isLoaded) fit();
      else a.addEventListener("DOMLoaded", fit);
    });
    return () => anims.forEach((a) => a && a.destroy());
  }, []);

  useEffect(() => {
    let raf;
    let last = performance.now();
    const start = last;

    const frame = (now) => {
      const dt = Math.min((now - last) / 1000, 0.05);
      last = now;
      const time = (now - start) / 1000;

      // --- conversation director -------------------------------------------
      // Runs before the walk step so a decision made this frame (stop, face
      // each other, resume) takes effect on this frame's positions.
      const chat = chatRef.current;
      const uiOpen = openIdRef.current !== null;

      const endTalk = () => {
        chat.phase = "idle";
        chat.script = null;
        chat.line = -1;
        chat.nextMeetAt =
          time + MEET_EVERY[0] + Math.random() * (MEET_EVERY[1] - MEET_EVERY[0]);
        // A beat of standing together before they part, rather than snapping
        // back into a walk on the frame the last line clears.
        states.forEach((s) => (s.pauseUntil = time + 0.6));
        setChatting(false);
        clearSpeech();
      };

      if (frozen || states.length < 2) {
        // no conversation without motion
      } else if (chat.phase === "idle") {
        if (!uiOpen && time >= chat.nextMeetAt) {
          planMeetup(states, time, WALK_OPTS);
          chat.phase = "approach";
          chat.approachUntil = time + 7;
        }
      } else if (chat.phase === "approach") {
        if (uiOpen) {
          // You opened a terminal mid-approach — drop it and try again later
          chat.phase = "idle";
          chat.nextMeetAt = time + 12;
        } else if (
          (!states[0].walking && !states[1].walking) ||
          time > chat.approachUntil
        ) {
          chat.script = CHATS[chat.scriptIdx % CHATS.length];
          // Cycle rather than pick at random, so you don't get the same
          // exchange twice running while others go unseen.
          chat.scriptIdx += 1;
          chat.line = -1;
          chat.lineUntil = time + 0.5; // beat to notice each other first
          chat.phase = "talk";
          setChatting(true);
          // Drop whatever solo one-liner was still up, so the notice beat is
          // silent and the exchange opens on its own first line.
          clearSpeech();
        }
      } else if (chat.phase === "talk") {
        if (uiOpen) {
          endTalk();
        } else if (time >= chat.lineUntil) {
          chat.line += 1;
          if (chat.line >= chat.script.length) {
            endTalk();
          } else {
            const [who, text] = chat.script[chat.line];
            chat.lineUntil = time + lineSeconds(text);
            showSpeech(who, text, true);
          }
        }
      }

      const talking = chat.phase === "talk";
      const approaching = chat.phase === "approach";

      if (talking || approaching) {
        // Ground wash follows the midpoint of the pair
        const mid = ((states[0].pos + states[1].pos) / 2) * 100;
        if (perchRef.current)
          perchRef.current.style.setProperty("--spot", `${mid}%`);
      }

      states.forEach((st, i) => {
        const host = hostRefs.current[i];
        if (!host) return;

        // While converging, whichever one arrives first waits instead of
        // wandering off on a fresh random walk before the other lands.
        if (approaching && !st.walking) st.pauseUntil = time + 0.4;

        st.frozenByUi = frozen || openIdRef.current === AGENTS[i].id || talking;
        stepWalk(st, states, time, dt, WALK_OPTS);

        // Turn to the partner for the duration of the conversation. Overrides
        // the travel-direction facing the engine leaves behind, which would
        // otherwise have them talking to each other's backs.
        if (talking) st.facing = states[1 - i].pos > st.pos ? 1 : -1;

        host.style.left = `${st.pos * 100}%`;
        const faces = CLIPS[i % CLIPS.length].faces;
        host.style.setProperty("--flip", faces === 0 ? 1 : st.facing * faces);

        // Scrub the clip by cumulative distance covered, not by wall clock.
        // The legs then physically cannot outrun the ground, and because the
        // odometer never resets between walks the playhead can never snap —
        // a new walk resumes exactly at the pose the last one ended on.
        const anim = animsRef.current[i];
        if (anim && anim.totalFrames) {
          if (st.clipDist === undefined) st.clipDist = 0;
          if (st.walking) {
            st.clipDist += st.moved;
          } else {
            // Finish the current stride at walking cadence instead of
            // freezing mid-step, then hold at the nearest foot-contact pose
            // (every half cycle). These clips have no idle pose, so a hard
            // stop leaves the character stranded mid-air.
            const half = LOOP_DISTANCE / 2;
            const rem = st.clipDist % half;
            if (rem > 1e-4 && half - rem > 1e-4) {
              st.clipDist += Math.min(dt * WALK_OPTS.speed, half - rem);
            }
          }
          const phase = (st.clipDist / LOOP_DISTANCE) % 1;
          anim.goToAndStop(phase * (anim.totalFrames - 1), true);
        }
      });

      raf = requestAnimationFrame(frame);
    };
    raf = requestAnimationFrame(frame);
    return () => cancelAnimationFrame(raf);
  }, [frozen, states, showSpeech, clearSpeech]);

  // Solo thought bubbles between conversations. Stands down while the two are
  // meeting or mid-exchange — the director owns the bubble then.
  useEffect(() => {
    if (frozen) return;
    let i = 0;
    const tick = () => {
      if (chatRef.current.phase !== "idle" || openIdRef.current !== null) return;
      const agent = AGENTS[i % AGENTS.length];
      showSpeech(
        i % AGENTS.length,
        agent.phrases[Math.floor(Math.random() * agent.phrases.length)],
        false,
        3200
      );
      i += 1;
    };
    const id = window.setInterval(tick, 6500);
    const first = window.setTimeout(tick, 2200);
    return () => {
      window.clearInterval(id);
      window.clearTimeout(first);
    };
  }, [frozen, showSpeech]);

  // Open one terminal and the other one leans in with a comment. Cheap, but it
  // turns a click on one character into a moment involving both.
  useEffect(() => {
    if (!openId || frozen) return;
    const other = AGENTS.findIndex((a) => a.id !== openId);
    if (other < 0) return;
    const t = window.setTimeout(() => {
      showSpeech(
        other,
        PEEKS[Math.floor(Math.random() * PEEKS.length)],
        false,
        3600
      );
    }, 1100);
    return () => window.clearTimeout(t);
  }, [openId, frozen, showSpeech]);

  const toggle = useCallback(
    (id) => setOpenId((cur) => (cur === id ? null : id)),
    []
  );

  useEffect(() => {
    if (!openId) return;
    const onKey = (e) => e.key === "Escape" && setOpenId(null);
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [openId]);

  // Positions are mutated by the rAF loop rather than held in state, so read
  // them at render time to decide which way a bubble should lean.
  const speaking = speech ? speech.i : -1;
  const listening = speech && speech.chat ? 1 - speech.i : -1;
  const bubbleShift =
    speech && speech.chat
      ? (states[speech.i].pos <= states[1 - speech.i].pos ? -1 : 1) *
        BUBBLE_SHIFT
      : 0;

  return (
    <div
      className={`pj-agents-perch-lottie${chatting ? " is-chatting" : ""}`}
      ref={perchRef}
    >
      {/* Ground wash under the pair while they talk — a soft pool of light
          rather than a frame, so it reads as attention, not a container. */}
      <span className="lilottie-spot" aria-hidden="true" />

      {AGENTS.map((agent, i) => (
        <div
          key={agent.id}
          className="lilottie-agent"
          ref={(el) => (hostRefs.current[i] = el)}
          style={{ left: `${states[i].pos * 100}%` }}
        >
          {speaking === i && openId !== agent.id && (
            <div
              className={`lilottie-bubble${
                speech.chat ? " lilottie-bubble-chat" : ""
              }`}
              role="status"
              style={{
                "--bub-shift": `${bubbleShift}px`,
                "--accent": agent.hueA,
              }}
            >
              {speech.text}
            </div>
          )}

          {/* The one being spoken to shows a listening beat, so the pair reads
              as a conversation even on the frames only one of them has words. */}
          {listening === i && openId !== agent.id && (
            <span className="lilottie-listen" aria-hidden="true">
              <i />
              <i />
              <i />
            </span>
          )}

          {openId === agent.id && (
            <div className="lilottie-popover">
              <div className="lilottie-popover-bar">
                <span className="lilottie-dot lilottie-dot-r" />
                <span className="lilottie-dot lilottie-dot-y" />
                <span className="lilottie-dot lilottie-dot-g" />
                <span className="lilottie-popover-title">
                  {agent.name} · {agent.role}
                </span>
              </div>
              <div className="lilottie-popover-body">
                <p className="lilottie-line lilottie-line-cmd">{agent.cmd}</p>
                {agent.lines.map((line, li) => (
                  <p className="lilottie-line" key={li}>
                    {line}
                  </p>
                ))}
                <a
                  className="lilottie-popover-link"
                  href="/myspace"
                  style={{ color: agent.hueA }}
                  onClick={(e) => {
                    e.preventDefault();
                    history.push("/myspace");
                  }}
                >
                  meet all 9 live tools →
                </a>
              </div>
            </div>
          )}

          <button
            type="button"
            className="lilottie-hit"
            onClick={() => toggle(agent.id)}
            aria-label={`Chat with ${agent.name}, ${agent.role}`}
            aria-expanded={openId === agent.id}
          >
            <div
              className="lilottie-mount"
              ref={(el) => (mountRefs.current[i] = el)}
            />
          </button>
        </div>
      ))}
    </div>
  );
}

export default LilAgentsLottie;
